struct U { first: String, last: String } impl U { fn full(&self) -> String { format!("{} {}", self.first, self.last) } fn initials(&self) -> String { let mut s = String::new(); s.push(self.first.chars().next().unwrap()); s.push(self.last.chars().next().unwrap()); s } } fn main() { let u = U { first: String::from("Ada"), last: String::from("Lovelace") }; println!("{} {} {}", u.full(), u.initials(), u.full().len()); }
